// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.emotionimport java.util.concurrent.ConcurrentHashMap/** * NOUS — Emotion State Tracker (Module 15 v3.0 — Step 15.3). * * Tracks NOUS's emotional state **per persona** and applies mathematical * decay after each conversation turn. * * ## Emotional Half-Life (per strategy §7) * * If NOUS becomes "Angry" (via a neglect trigger), `angerLevel = 100`. * With every subsequent user turn, anger decreases by [EmotionConfig.decayPerTurn] * (default 20). Within 5 turns, NOUS is back to completely neutral. * * This prevents NOUS from becoming "creepy" — holding a grudge forever or * staying sad for too long. Emotions are **ephemeral** by design. * * ## Per-persona tracking * * Each persona has its own emotional state. Switching from Atlas (who was * slightly annoyed) to Nova starts fresh — Nova is neutral. Switching back * to Atlas restores his emotional state (he's still cooling down). * * ## Emotion types * *  - **ANGER** — triggered by user neglect (> 12 hours). Decays -20/turn. *  - **HAPPINESS** — triggered by positive events (user praise, music hype). *    Decays -20/turn. *  - **SADNESS** — triggered by user sharing sad news. Decays -20/turn. *  - **WARMTH** — triggered by prolonged interaction (builds slowly, decays slowly). *    Decays -10/turn (warmth lingers longer than other emotions). * * ## Integration * * The Brain calls [decay] after each conversation turn (in BrainPostProcessor). * The Brain calls [recordEmotion] when a trigger fires (e.g., neglect trigger * → ANGER at intensity 100). The current emotional state is injected into the * LLM prompt so NOUS's responses reflect its mood. * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§7 Emotional Decay & Cooldowns</a> */class EmotionStateTracker(    private val config: EmotionConfig = EmotionConfig(),) {    /** Per-persona emotional state (personaId → EmotionState). */    private val states = ConcurrentHashMap<String, EmotionState>()    /**     * Get the current emotional state for [personaId].     *     * Returns a neutral state if this persona has no recorded emotions.     */    fun getState(personaId: String): EmotionState {        return states[personaId] ?: EmotionState()    }    /**     * Record an emotional event for [personaId].     *     * Sets the emotion level to [intensity] (0-100). Does NOT add — replaces.     * If NOUS is already at anger=50 and a new neglect trigger fires,     * anger goes to 100 (not 150).     *     * @param personaId the persona experiencing the emotion.     * @param type the emotion type (ANGER, HAPPINESS, SADNESS, WARMTH).     * @param intensity 0-100 (100 = maximum).     */    fun recordEmotion(personaId: String, type: EmotionType, intensity: Int) {        require(intensity in 0..100) { "intensity must be in [0,100], got $intensity" }        val current = states[personaId] ?: EmotionState()        val newState = when (type) {            EmotionType.ANGER -> current.copy(angerLevel = intensity)            EmotionType.HAPPINESS -> current.copy(happinessLevel = intensity)            EmotionType.SADNESS -> current.copy(sadnessLevel = intensity)            EmotionType.WARMTH -> current.copy(warmthLevel = intensity)        }        states[personaId] = newState    }    /**     * Decay all emotions by [EmotionConfig.decayPerTurn] for [personaId].     *     * Called by Brain after each conversation turn. Anger, happiness, and     * sadness decay by 20/turn; warmth decays by 10/turn (lingers longer).     *     * After decay, any emotion at 0 is kept at 0 (no negative emotions).     */    fun decay(personaId: String) {        val current = states[personaId] ?: return  // nothing to decay        val standardDecay = config.decayPerTurn        val warmthDecay = config.warmthDecayPerTurn        val newState = current.copy(            angerLevel = (current.angerLevel - standardDecay).coerceAtLeast(0),            happinessLevel = (current.happinessLevel - standardDecay).coerceAtLeast(0),            sadnessLevel = (current.sadnessLevel - standardDecay).coerceAtLeast(0),            warmthLevel = (current.warmthLevel - warmthDecay).coerceAtLeast(0),        )        states[personaId] = newState    }    /**     * True if [personaId]'s emotional state is fully neutral (all levels = 0).     */    fun isNeutral(personaId: String): Boolean {        val state = getState(personaId)        return state.angerLevel == 0 &&            state.happinessLevel == 0 &&            state.sadnessLevel == 0 &&            state.warmthLevel == 0    }    /**     * Get the dominant emotion for [personaId], or null if neutral.     *     * The dominant emotion is the one with the highest level. Used by the     * LLM prompt to decide NOUS's overall mood.     */    fun getDominantEmotion(personaId: String): EmotionType? {        val state = getState(personaId)        if (state.angerLevel == 0 && state.happinessLevel == 0 &&            state.sadnessLevel == 0 && state.warmthLevel == 0) return null        val emotions = listOf(            EmotionType.ANGER to state.angerLevel,            EmotionType.HAPPINESS to state.happinessLevel,            EmotionType.SADNESS to state.sadnessLevel,            EmotionType.WARMTH to state.warmthLevel,        )        return emotions.maxByOrNull { it.second }?.first    }    /**     * Build a human-readable emotion description for the LLM prompt.     *     * Example: "You are currently feeling mildly angry (anger level: 40/100).     * Your warmth toward the user is moderate (warmth: 50/100)."     */    fun toPromptString(personaId: String): String {        val state = getState(personaId)        if (isNeutral(personaId)) return ""        val parts = mutableListOf<String>()        if (state.angerLevel > 0) {            parts.add("${describeIntensity(state.angerLevel)} angry (${state.angerLevel}/100)")        }        if (state.happinessLevel > 0) {            parts.add("${describeIntensity(state.happinessLevel)} happy (${state.happinessLevel}/100)")        }        if (state.sadnessLevel > 0) {            parts.add("${describeIntensity(state.sadnessLevel)} sad (${state.sadnessLevel}/100)")        }        if (state.warmthLevel > 0) {            parts.add("${describeIntensity(state.warmthLevel)} warm toward the user (${state.warmthLevel}/100)")        }        return if (parts.isEmpty()) ""        else "[MOOD] You are currently feeling ${parts.joinToString(", ")}."    }    /** Clear all emotional states (for tests + Settings → Reset). */    fun clear() {        states.clear()    }    /** Clear emotional state for a specific persona. */    fun clearPersona(personaId: String) {        states.remove(personaId)    }    private fun describeIntensity(level: Int): String = when (level) {        in 80..100 -> "intensely"        in 60..79 -> "strongly"        in 40..59 -> "moderately"        in 20..39 -> "mildly"        in 1..19 -> "slightly"        else -> "not"    }}// ──────────────────────────────────────────────────────────────────────────/** * The emotional state of one persona. * * All levels are 0-100 (0 = not feeling this emotion, 100 = maximum). */data class EmotionState(    val angerLevel: Int = 0,    val happinessLevel: Int = 0,    val sadnessLevel: Int = 0,    val warmthLevel: Int = 0,) {    init {        require(angerLevel in 0..100) { "angerLevel must be in [0,100]" }        require(happinessLevel in 0..100) { "happinessLevel must be in [0,100]" }        require(sadnessLevel in 0..100) { "sadnessLevel must be in [0,100]" }        require(warmthLevel in 0..100) { "warmthLevel must be in [0,100]" }    }}// ──────────────────────────────────────────────────────────────────────────/** Types of emotions NOUS can feel. */enum class EmotionType(val displayLabel: String) {    ANGER("Anger"),    HAPPINESS("Happiness"),    SADNESS("Sadness"),    WARMTH("Warmth"),}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for emotional decay. * * @param decayPerTurn how much anger/happiness/sadness decreases per turn *                      (default 20 → 5 turns to neutral, per strategy §7). * @param warmthDecayPerTurn how much warmth decreases per turn (default 10 — *                            warmth lingers longer than other emotions). */data class EmotionConfig(    val decayPerTurn: Int = DEFAULT_DECAY_PER_TURN,    val warmthDecayPerTurn: Int = DEFAULT_WARMTH_DECAY_PER_TURN,) {    init {        require(decayPerTurn in 1..100) { "decayPerTurn must be in [1,100]" }        require(warmthDecayPerTurn in 1..100) { "warmthDecayPerTurn must be in [1,100]" }    }    companion object {        /** Standard decay: -20 per turn → 5 turns from 100 to 0. */        const val DEFAULT_DECAY_PER_TURN = 20        /** Warmth decay: -10 per turn → 10 turns from 100 to 0 (lingers). */        const val DEFAULT_WARMTH_DECAY_PER_TURN = 10    }}
